async def act(page):
    """
    From the current page state (already on the Search Results page), perform these new actions:
    1. Best-effort dismiss any visible popup overlay that may block interactions.
    2. Use the complementary region's search input (role=searchbox named "Search") to enter 'GPT'.
    3. Trigger the search by clicking the Search button inside the complementary region (preferred) or pressing Enter.
    4. Wait for results in role="main", then click the third search result. Prefer the path
       main -> article (nth 2) -> heading(level=2) -> link. Use guarded counts before .nth().

    The final action (the last operation) is the click on the third result's link.
    """
    import re

    # 1) Best-effort: dismiss any visible modal/overlay that could block clicks
    try:
        # Common close control names/labels
        close_candidates = page.get_by_role("button", name=re.compile(r"^(×|x|close|dismiss)$", re.IGNORECASE))
        if await close_candidates.count() > 0:
            try:
                await close_candidates.first.click(force=True)
            except Exception:
                # ignore and continue
                pass
        else:
            alt = page.get_by_role("button", name=re.compile(r"close", re.IGNORECASE))
            if await alt.count() > 0:
                try:
                    await alt.first.click(force=True)
                except Exception:
                    pass
    except Exception:
        # best-effort only; continue
        pass

    # 2) Locate the complementary region which holds the visible search widget
    comp = page.get_by_role("complementary")
    await comp.first.wait_for(state="visible")

    # Preferred: role=searchbox named 'Search'; fallback to any searchbox or textbox in the complementary region
    search_input = None
    if await comp.first.get_by_role("searchbox", name="Search").count() > 0:
        search_input = comp.first.get_by_role("searchbox", name="Search").first
    elif await comp.first.get_by_role("searchbox").count() > 0:
        search_input = comp.first.get_by_role("searchbox").first
    elif await comp.first.get_by_role("textbox").count() > 0:
        search_input = comp.first.get_by_role("textbox").first

    if search_input is None:
        raise RuntimeError("Could not locate the site's search input inside the complementary region.")

    await search_input.wait_for(state="visible")
    await search_input.fill("GPT")

    # 3) Trigger the search: prefer the Search button within the complementary region
    search_btn = None
    if await comp.first.get_by_role("button", name=re.compile(r"search", re.IGNORECASE)).count() > 0:
        search_btn = comp.first.get_by_role("button", name=re.compile(r"search", re.IGNORECASE)).first
    elif await comp.first.get_by_role("button").count() > 0:
        # pragmatic fallback: first button in complementary region
        search_btn = comp.first.get_by_role("button").first

    if search_btn is not None:
        try:
            await search_btn.click()
        except Exception:
            # If normal click is blocked by overlay, force it
            await search_btn.click(force=True)
    else:
        # Final fallback: press Enter in the search input
        await search_input.press("Enter")

    # 4) Wait for results to appear in role="main" (fallback to networkidle)
    main = page.get_by_role("main")
    try:
        await main.first.wait_for(state="visible", timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            pass

    # 5) Locate articles under main and ensure at least 3 results, then click the 3rd
    articles = page.get_by_role("main").get_by_role("article")
    count = await articles.count()
    if count >= 3:
        third = articles.nth(2)
        # Prefer the article -> heading(level=2) -> link path
        if await third.get_by_role("heading", level=2).count() > 0:
            heading = third.get_by_role("heading", level=2).first
            await heading.wait_for(state="visible")
            if await heading.get_by_role("link").count() > 0:
                link = heading.get_by_role("link").first
                try:
                    await link.click()
                except Exception:
                    await link.click(force=True)
                return
        # Fallback: click the first link inside the article
        if await third.get_by_role("link").count() > 0:
            fallback_link = third.get_by_role("link").first
            try:
                await fallback_link.click()
            except Exception:
                await fallback_link.click(force=True)
            return
        raise RuntimeError("Third article had no clickable link inside it.")

    # If there are fewer than 3 article children under main, try a more permissive fallback:
    # look for headings level=2 anywhere inside main and click the third such heading's link
    headings = main.first.get_by_role("heading", level=2)
    hcount = await headings.count()
    if hcount >= 3:
        target_heading = headings.nth(2)
        await target_heading.wait_for(state="visible")
        if await target_heading.get_by_role("link").count() > 0:
            try:
                await target_heading.get_by_role("link").first.click()
            except Exception:
                await target_heading.get_by_role("link").first.click(force=True)
            return

    # Last fallback: As a pragmatic final attempt, click the third link found inside the main region
    links_in_main = main.first.get_by_role("link")
    link_count = await links_in_main.count()
    if link_count >= 3:
        try:
            await links_in_main.nth(2).click()
        except Exception:
            await links_in_main.nth(2).click(force=True)
        return

    raise RuntimeError(f"Unable to locate a third search result to click (articles:{count}, headings:{hcount}, links:{link_count if 'link_count' in locals() else 0}).")

